class Solution {public:vector<int>solve(int n,vector<vector<int>>edges){int m=edges.size();if(!m)return{};vector<vector<int>>a(n);vector<int>degree(n),index(n);for(int id=0;id<m;id++){a[edges[id][0]].push_back(id);degree[edges[id][0]]++;degree[edges[id][1]]--;}int start=edges[0][0],plus=0,minus=0;for(int v=0;v<n;v++)if(degree[v]==1){plus++;start=v;}else if(degree[v]==-1)minus++;else if(degree[v])return{-1};if(!((plus==0&&minus==0)||(plus==1&&minus==1)))return{-1};vector<int>vertices{start},enter{-1},out;while(!vertices.empty()){int u=vertices.back();if(index[u]<(int)a[u].size()){int id=a[u][index[u]++];vertices.push_back(edges[id][1]);enter.push_back(id);}else{vertices.pop_back();int id=enter.back();enter.pop_back();if(id>=0)out.push_back(id);}}if((int)out.size()!=m)return{-1};reverse(out.begin(),out.end());return out;}};